import time, random

class APIMock:
    def __init__(self):
        self.intentos = 0
    def fetch(self):
        self.intentos += 1
        if self.intentos < 3:
            return 429, None
        return 200, {'data': 'lote_completado', 'cursor': 'next_xyz'}

api = APIMock()
base_delay = 0.1

for attempt in range(5):
    status, payload = api.fetch()
    if status == 200:
        print(f'Exito en intento {attempt+1}: {payload}')
        break
    elif status == 429:
        sleep_t = (base_delay * (2 ** attempt)) + random.uniform(0.01, 0.05)
        print(f'Intento {attempt+1} fallido (429). Esperando {sleep_t:.3f}s...')
        time.sleep(sleep_t)

